import Stripe from 'stripe'

/**
 * Stripe Node.js SDK client.
 *
 * Server-side only. Never expose STRIPE_SECRET_KEY to the client.
 *
 * Lazy singleton — constructed on first use so module evaluation
 * never throws at build time when the env var is absent.
 */
let _stripe: Stripe | null = null

export function getStripe(): Stripe {
  if (!_stripe) {
    const key = process.env.STRIPE_SECRET_KEY
    if (!key) {
      throw new Error(
        '[InkOS] STRIPE_SECRET_KEY is not set. Set it in .env.local before using the Stripe client.',
      )
    }
    const apiVersion = (process.env.STRIPE_API_VERSION ?? '2024-06-20') as Stripe.LatestApiVersion
    _stripe = new Stripe(key, {
      apiVersion,
      typescript: true,
      appInfo: {
        name: 'InkOS',
        url: process.env.NEXT_PUBLIC_APP_URL,
      },
    })
  }
  return _stripe
}

/** Convenience proxy — use `stripe.x` in existing code unchanged. */
export const stripe: Stripe = new Proxy({} as Stripe, {
  get(_target, prop) {
    return (getStripe() as unknown as Record<string | symbol, unknown>)[prop]
  },
})

import { getStripe } from './client'
import type Stripe from 'stripe'

/**
 * Verify a Stripe webhook signature and parse the event.
 *
 * Uses Stripe's built-in constructEvent which:
 *  - Validates the `stripe-signature` header HMAC (SHA-256)
 *  - Rejects events older than `tolerance` seconds (default 300 = 5 minutes)
 *
 * Throws `Stripe.errors.StripeSignatureVerificationError` on invalid sig or stale timestamp.
 * Callers must catch and return 401.
 */
export function verifyStripeWebhook(
  rawBody: string,
  signatureHeader: string,
  webhookSecret: string,
): Stripe.Event {
  const stripe = getStripe()
