import { type NextRequest, NextResponse } from 'next/server'
import type Stripe from 'stripe'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { verifyStripeWebhook } from '@/lib/stripe/webhook-verify'
import { insertWebhookEvent } from '@/lib/payments/webhook-events'
import {
  RPC,
  type StripeConnectedAccountUpdateFromWebhookArgs,
  type StripeChargeUpdateStatusFromWebhookArgs,
  type StripeDisputeRecordArgs,
  type StripeDisputeUpdateStatusFromWebhookArgs,
  type ConnectedAccountOnboardingStatus,
  type Currency,
  type StripeChargeStatus,
  type StripeDisputeStatus,
  cents,
} from '@/lib/payments/contracts'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { webhookRatelimit } from '@/lib/rate-limit'

export const dynamic = 'force-dynamic'

/**
 * Stripe webhook handler — Sprint 13 Stripe Connect Express.
 *
 * Security order (must not be reordered):
 *  1. STRIPE_WEBHOOK_SECRET presence check
 *  2. IP-based rate limit (webhookRatelimit)
 *  3. Stripe signature verification via stripe.webhooks.constructEvent (5-min tolerance)
 *  4. Idempotency: insertWebhookEvent RPC (INSERT … ON CONFLICT DO NOTHING)
 *  5. Typed event dispatch via switch on event.type
 *  6. RPC writes via service-role client (bypasses RLS)
 *
 * INVARIANT 3: insertWebhookEvent is always the first DB write.
 * INVARIANT 6: stripe_charges is webhook-only write from app code.
 * INVARIANT 7: Dodo and Stripe abstractions never share a module.
 */

export async function POST(req: NextRequest): Promise<NextResponse> {
  // Step 1: Guard — webhook secret must be configured
  const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET
  if (!webhookSecret) {
    logger.error('STRIPE_WEBHOOK_SECRET is not set — stripe webhook handler disabled')
    return NextResponse.json({ error: 'webhook not configured' }, { status: 503 })
  }

  // Step 2: Rate limit by IP
  const ip = getClientIp(req)
  const rl = await webhookRatelimit.limit(ip)
  if (!rl.success) {
    logger.warn({ ip }, 'stripe webhook: rate limit exceeded')
    return NextResponse.json({ error: 'too many requests' }, { status: 429 })
  }

  // Step 3: Read raw body — MUST be string; Stripe HMAC is over raw bytes
  const rawBody = await req.text()
  const sig = req.headers.get('stripe-signature')

  if (!sig) {
    logger.warn({ ip }, 'stripe webhook: missing stripe-signature header')
    return NextResponse.json({ error: 'missing stripe-signature' }, { status: 400 })
  }

  // Step 4: Verify signature — throws on invalid sig or stale timestamp (>5 min)
  let event: Stripe.Event
  try {
    event = verifyStripeWebhook(rawBody, sig, webhookSecret)
  } catch (e) {
    const msg = e instanceof Error ? e.message : 'unknown'
    logger.warn({ msg, ip }, 'stripe webhook: signature verification failed')
    await logAuditAction(
      null,
      'webhook_signature_mismatch',
      null,
      { source: 'stripe', sig_present: true },
      null,
    )
    return NextResponse.json({ error: 'invalid signature' }, { status: 401 })
  }

  const supabase = createServiceRoleClient()

  // Step 5: Idempotency — first DB write, replay guard
  let insertResult: { inserted: boolean; id: string | null }
  try {
    insertResult = await insertWebhookEvent(supabase, {
      source: 'stripe',
      eventId: event.id,
      eventType: event.type,
      payload: event,
      signatureVerified: true,
    })
  } catch (e) {
    const msg = e instanceof Error ? e.message : 'unknown'
    logger.error({ err: msg, eventId: event.id }, 'stripe webhook: failed to insert webhook_event row')
    return NextResponse.json({ error: 'internal error' }, { status: 500 })
  }

  if (!insertResult.inserted) {
    logger.info({ eventId: event.id }, 'stripe webhook: replay detected — skipping processing')
    return NextResponse.json({ received: true, replay: true })
  }

  // Step 6: Typed dispatch
  try {
    await processStripeEvent(event, supabase)
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err)
    logger.error({ err: msg, eventId: event.id, type: event.type }, 'stripe webhook: processing failed')
    return NextResponse.json({ error: 'processing failed' }, { status: 500 })
  }

  return NextResponse.json({ received: true, event_id: event.id, event_type: event.type })
}

// ---------------------------------------------------------------------------
// Event dispatcher
// ---------------------------------------------------------------------------

async function processStripeEvent(
  event: Stripe.Event,
  supabase: ReturnType<typeof createServiceRoleClient>,
): Promise<void> {
  logger.info({ type: event.type, eventId: event.id }, 'stripe webhook: processing')

  switch (event.type) {
    case 'account.updated':
      await handleAccountUpdated(event.data.object as Stripe.Account, supabase)
      break

    case 'payment_intent.succeeded':
      await handlePaymentIntentStatusChange(
        event.data.object as Stripe.PaymentIntent,
        'succeeded',
        supabase,
      )
      break

    case 'payment_intent.payment_failed':
      await handlePaymentIntentStatusChange(
        event.data.object as Stripe.PaymentIntent,
        'requires_payment_method',
        supabase,
      )
      break

    case 'payment_intent.canceled':
      await handlePaymentIntentStatusChange(
        event.data.object as Stripe.PaymentIntent,
        'canceled',
        supabase,
      )
      break

    case 'charge.dispute.created':
      await handleDisputeCreated(event.data.object as Stripe.Dispute, supabase)
      break

    case 'charge.dispute.closed':
      await handleDisputeClosed(event.data.object as Stripe.Dispute, supabase)
      break

    default:
      logger.info({ type: event.type, eventId: event.id }, 'stripe webhook: event recorded, not processed')
  }
}

// ---------------------------------------------------------------------------
// account.updated
// ---------------------------------------------------------------------------

async function handleAccountUpdated(
  account: Stripe.Account,
  supabase: ReturnType<typeof createServiceRoleClient>,
): Promise<void> {
  const onboardingStatus = deriveOnboardingStatus(account)
  const capabilities = account.capabilities ?? {}
  const restrictedReason = account.requirements?.disabled_reason ?? null

  // current_deadline is a unix timestamp (seconds) — convert to ISO string or null
  const currentDeadline = account.requirements?.current_deadline
  const requirementsDueBy = currentDeadline
    ? new Date(currentDeadline * 1_000).toISOString()
    : null

  const args: StripeConnectedAccountUpdateFromWebhookArgs = {
    accountId: account.id,
    onboardingStatus,
    capabilities: {
      charges_enabled: account.charges_enabled ?? false,
      payouts_enabled: account.payouts_enabled ?? false,
      transfers: (capabilities as Record<string, string>)['transfers'] === 'active',
      tax_reporting_us_1099_nec:
        (capabilities as Record<string, string>)['tax_reporting_us_1099_nec'] === 'active',
    },
    country: account.country ?? 'US',
    defaultCurrency: (account.default_currency ?? 'usd') as Currency,
    restrictedReason,
    requirementsDueBy,
  }

  const { data, error } = await supabase.rpc(RPC.STRIPE_CONNECTED_ACCOUNT_UPDATE_FROM_WEBHOOK, {
    p_account_id: args.accountId,
    p_onboarding_status: args.onboardingStatus,
    p_capabilities: args.capabilities,
    p_country: args.country,
    p_default_currency: args.defaultCurrency,
    p_restricted_reason: args.restrictedReason,
    p_requirements_due_by: args.requirementsDueBy,
  })

  if (error) {
    logger.error({ err: error, accountId: account.id }, 'stripe webhook: account.updated RPC failed')
    throw error
  }

  logger.info({ accountId: account.id, result: data }, 'stripe webhook: account.updated processed')
}

function deriveOnboardingStatus(account: Stripe.Account): ConnectedAccountOnboardingStatus {
  if (account.charges_enabled && account.payouts_enabled) return 'active'

  const disabledReason = account.requirements?.disabled_reason
  if (disabledReason) return 'restricted'

  const errors = account.requirements?.errors ?? []
  if (errors.length > 0) return 'restricted'

  return 'pending'
}

// ---------------------------------------------------------------------------
// payment_intent.succeeded / payment_failed / canceled
// ---------------------------------------------------------------------------

async function handlePaymentIntentStatusChange(
  pi: Stripe.PaymentIntent,
  status: StripeChargeStatus,
  supabase: ReturnType<typeof createServiceRoleClient>,
): Promise<void> {
  // latest_charge is the charge ID if payment succeeded.
  // At PaymentIntent stage we do NOT fetch the full Charge object — that would
  // require an API call in the webhook hot path which is forbidden.
  const latestCharge = pi.latest_charge
  const chargeId = typeof latestCharge === 'string' ? latestCharge : (latestCharge?.id ?? null)

  const args: StripeChargeUpdateStatusFromWebhookArgs = {
    paymentIntentId: pi.id,
    status,
    chargeId,
    // transfer_id deferred — requires charge.retrieve which we forbid in webhook hot path.
    // S15+ may add async backfill via BullMQ.
    transferId: null,
    // application_fee_id deferred — same reason as transferId above.
    applicationFeeId: null,
  }

  const { data, error } = await supabase.rpc(RPC.STRIPE_CHARGE_UPDATE_STATUS_FROM_WEBHOOK, {
    p_payment_intent_id: args.paymentIntentId,
    p_status: args.status,
    p_charge_id: args.chargeId,
    p_transfer_id: args.transferId,
    p_application_fee_id: args.applicationFeeId,
  })

  if (error) {
    logger.error({ err: error, piId: pi.id, status }, 'stripe webhook: charge status update RPC failed')
    throw error
  }

  logger.info({ piId: pi.id, status, result: data }, 'stripe webhook: payment_intent status updated')
}

// ---------------------------------------------------------------------------
// charge.dispute.created
// ---------------------------------------------------------------------------

async function handleDisputeCreated(
  dispute: Stripe.Dispute,
  supabase: ReturnType<typeof createServiceRoleClient>,
): Promise<void> {
  // Resolve studio_id from the charge via stripe_charges table
  const chargeId = typeof dispute.charge === 'string' ? dispute.charge : dispute.charge?.id
  if (!chargeId) {
    logger.warn({ disputeId: dispute.id }, 'stripe webhook: dispute missing charge id — skipping')
    return
  }

  const studioId = await resolveStudioIdFromCharge(chargeId, supabase)
  if (!studioId) {
    logger.warn({ disputeId: dispute.id, chargeId }, 'stripe webhook: could not resolve studio_id for dispute')
    return
  }

  const evidenceDueBy = dispute.evidence_details?.due_by
    ? new Date(dispute.evidence_details.due_by * 1_000).toISOString()
    : new Date(Date.now() + 7 * 24 * 60 * 60 * 1_000).toISOString() // fallback: 7 days

  const args: StripeDisputeRecordArgs = {
    studioId,
    disputeId: dispute.id,
    chargeId,
    reason: dispute.reason,
    status: dispute.status as StripeDisputeStatus,
    amountCents: cents(dispute.amount),
    currency: (dispute.currency ?? 'usd') as Currency,
    evidenceDueBy,
  }

  const { data, error } = await supabase.rpc(RPC.STRIPE_DISPUTE_RECORD, {
    p_studio_id: args.studioId,
    p_dispute_id: args.disputeId,
    p_charge_id: args.chargeId,
    p_reason: args.reason,
    p_status: args.status,
    p_amount_cents: args.amountCents,
    p_currency: args.currency,
    p_evidence_due_by: args.evidenceDueBy,
  })

  if (error) {
    logger.error({ err: error, disputeId: dispute.id }, 'stripe webhook: dispute.created RPC failed')
    throw error
  }

  logger.info({ disputeId: dispute.id, studioId, result: data }, 'stripe webhook: dispute recorded')
}

// ---------------------------------------------------------------------------
// charge.dispute.closed
// ---------------------------------------------------------------------------

async function handleDisputeClosed(
  dispute: Stripe.Dispute,
  supabase: ReturnType<typeof createServiceRoleClient>,
): Promise<void> {
  // resolved_amount_cents: if lost, the disputed amount was clawed back
  const resolvedAmountCents =
    dispute.status === 'lost' ? cents(dispute.amount) : null

  // Stripe doesn't expose a dedicated "resolved_at" timestamp; use now
  const resolvedAt = new Date().toISOString()

  const args: StripeDisputeUpdateStatusFromWebhookArgs = {
    disputeId: dispute.id,
    status: dispute.status as StripeDisputeStatus,
    resolvedAt,
    resolvedAmountCents,
  }

  const { data, error } = await supabase.rpc(RPC.STRIPE_DISPUTE_UPDATE_STATUS_FROM_WEBHOOK, {
    p_dispute_id: args.disputeId,
    p_status: args.status,
    p_resolved_at: args.resolvedAt,
    p_resolved_amount_cents: args.resolvedAmountCents,
  })

  if (error) {
    logger.error({ err: error, disputeId: dispute.id }, 'stripe webhook: dispute.closed RPC failed')
    throw error
  }

  logger.info({ disputeId: dispute.id, status: dispute.status, result: data }, 'stripe webhook: dispute closed')
}

// ---------------------------------------------------------------------------
// Lookup helpers
// ---------------------------------------------------------------------------

async function resolveStudioIdFromCharge(
  chargeId: string,
  supabase: ReturnType<typeof createServiceRoleClient>,
): Promise<string | null> {
  const { data } = await supabase
    .from('stripe_charges')
    .select('studio_id')
    .eq('charge_id', chargeId)
    .maybeSingle()
  return data?.studio_id ?? null
}

