export function getStripe(): Stripe {
  if (!_stripe) {
    const key = process.env.STRIPE_SECRET_KEY
    if (!key) {
      throw new Error(
        '[InkOS] STRIPE_SECRET_KEY is not set. Set it in .env.local before using the Stripe client.',
      )
    }
    const appUrl = process.env.NEXT_PUBLIC_APP_URL

    _stripe = new Stripe(key, {
      // Stripe v22 requires the dahlia version literal; the SDK validates this at the type level.
      apiVersion: '2026-04-22.dahlia',
      // exactOptionalPropertyTypes: url must be string (not undefined) — only include if set.
      appInfo: appUrl
        ? { name: 'InkOS', url: appUrl }
        : { name: 'InkOS' },
    })
  }
  return _stripe
}

/** Convenience proxy — use `stripe.x` in existing code unchanged. */
export const stripe: Stripe = new Proxy({} as Stripe, {
  get(_target, prop) {
    return (getStripe() as unknown as Record<string | symbol, unknown>)[prop]
  },
})
